example.code:
// Parse a semantic version string
var version = SemanticVersion.Parse("1.2.3-alpha.1+build");
Console.WriteLine(version.Major); // 1
Console.WriteLine(version.Minor); // 2
Console.WriteLine(version.Patch); // 3
Console.WriteLine(version.IsPrerelease); // true
Console.WriteLine(version.PrereleaseLabels); // ["alpha", "1"]
Console.WriteLine(version.HasMetadata); // true
Console.WriteLine(version.Metadata); // ["build"]

// Create and compare versions
var v1 = new SemanticVersion(1, 0, 0, "alpha");
var v2 = new SemanticVersion(1, 0, 0);
Console.WriteLine(v1 < v2); // true (prerelease versions have lower precedence)

// Get next version
Console.WriteLine(v2.NextPatchVersion()); // 1.0.1
Console.WriteLine(v2.NextMinorVersion()); // 1.1.0
Console.WriteLine(v2.NextMajorVersion()); // 2.0.0

// NuGet format examples
var range1 = SemanticVersionRange.ParseNuGet("[1.0.0, 2.0.0)"); // >=1.0.0 and <2.0.0
var range2 = SemanticVersionRange.ParseNuGet("1.0.0");          // >=1.0.0
var range3 = SemanticVersionRange.ParseNuGet("[1.0.0]");        // ==1.0.0

// npm format examples
var range4 = SemanticVersionRange.ParseNpm(">=1.0.0 <2.0.0");  // >=1.0.0 and <2.0.0
var range5 = SemanticVersionRange.ParseNpm("<=2.0.0");           // <=2.0.0

// Check if a version satisfies the range
var version = SemanticVersion.Parse("1.5.0");
Console.WriteLine(range1.Satisfies(version)); // true

member.summary:
            Indicates that the type is culture insensitive. This can be used to suppress rules such as MA0075, MA0076.

[CultureInsensitiveType]class Foo { }

[assembly: CultureInsensitiveType(typeof(Foo))]
